const std = @import("std");

pub fn main() !void {
    const text = "banana";
    const n = text.len;
    var suffixes: [6][7]u8 = undefined;
    var indices: [6]usize = undefined;

    for (0..n) |i| {
        indices[i] = i;
        for (0..n - i) |j| {
            suffixes[i][j] = text[i + j];
        }
        suffixes[i][n - i] = 0;
    }

    std.sort.block(usize, indices, {}, struct {
        fn lessThan(_: void, a: usize, b: usize) bool {
            var i: usize = 0;
            while (text[a + i] == text[b + i] and a + i < n and b + i < n) { i += 1; }
            return if (a + i >= n) true else if (b + i >= n) false else text[a + i] < text[b + i];
        }
    }.lessThan);

    for (indices) |idx| std.debug.print("{}: {s}\n", .{idx, text[idx..]});
}

